[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700&family=Playfair+Display:wght@700;800&display=swap" rel="stylesheet" />
  <style>
    /* ── Reset & Variables ─────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --red:        #C41E3A;
      --red-dark:   #a01830;
      --red-light:  #e8293f;
      --navy:       #1B3A5C;
      --navy-dark:  #122844;
      --navy-light: #254d7a;
      --white:      #ffffff;
      --off-white:  #f8f6f3;
      --warm-gray:  #f0ede8;
      --mid-gray:   #9ca3af;
      --text:       #1a1a1a;
      --text-light: #4b5563;
      --border:     #e5e0d8;
      --shadow-sm:  0 1px 3px rgba(0,0,0,.08);
      --shadow-md:  0 4px 16px rgba(0,0,0,.10);
      --shadow-lg:  0 12px 40px rgba(0,0,0,.14);
      --radius:     8px;
      --transition: 0.22s ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      color: var(--text);
      background: var(--white);
      line-height: 1.65;
      overflow-x: hidden;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: inherit; }
    ul { list-style: none; }

    /* ── Utilities ─────────────────────────────────────────── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .section { padding: 88px 0; }
    .section-sm { padding: 64px 0; }
    .sr-only { position: absolute; width:1px; height:1px; overflow:hidden; clip:rect(0,0,0,0); }

    .btn {
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      padding: 13px 28px; border-radius: var(--radius); font-weight: 600;
      font-size: 15px; border: 2px solid transparent; transition: all var(--transition);
      white-space: nowrap;
    }
    .btn-primary { background: var(--red); color: var(--white); border-color: var(--red); }
    .btn-primary:hover { background: var(--red-dark); border-color: var(--red-dark); transform: translateY(-1px); box-shadow: 0 4px 14px rgba(196,30,58,.35); }
    .btn-secondary { background: transparent; color: var(--white); border-color: rgba(255,255,255,.7); }
    .btn-secondary:hover { background: rgba(255,255,255,.12); border-color: var(--white); }
    .btn-outline { background: transparent; color: var(--red); border-color: var(--red); }
    .btn-outline:hover { background: var(--red); color: var(--white); }
    .btn-navy { background: var(--navy); color: var(--white); border-color: var(--navy); }
    .btn-navy:hover { background: var(--navy-dark); border-color: var(--navy-dark); transform: translateY(-1px); }
    .btn-lg { padding: 16px 36px; font-size: 16px; }

    .tag {
      display: inline-block; padding: 4px 12px; border-radius: 100px;
      font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
    }
    .tag-red { background: rgba(196,30,58,.1); color: var(--red); }
    .tag-navy { background: rgba(27,58,92,.1); color: var(--navy); }

    .eyebrow {
      font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
      color: var(--red); margin-bottom: 12px;
    }
    .section-title {
      font-family: 'Playfair Display', serif;
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800; line-height: 1.15; color: var(--navy);
    }
    .section-subtitle {
      font-size: 17px; color: var(--text-light); margin-top: 16px; max-width: 620px;
    }
    .section-header { margin-bottom: 56px; }
    .section-header.centered { text-align: center; }
    .section-header.centered .section-subtitle { margin: 16px auto 0; }

    /* ── Top Utility Bar ───────────────────────────────────── */
    .utility-bar {
      background: var(--navy-dark); color: rgba(255,255,255,.8);
      font-size: 13px; padding: 7px 0;
    }
    .utility-bar .container {
      display: flex; align-items: center; justify-content: flex-end; gap: 24px;
    }
    .utility-bar a { color: rgba(255,255,255,.8); transition: color var(--transition); }
    .utility-bar a:hover { color: var(--white); }

    /* ── Header ────────────────────────────────────────────── */
    .site-header {
      background: var(--white); border-bottom: 1px solid var(--border);
      position: sticky; top: 0; z-index: 100;
      box-shadow: 0 2px 8px rgba(0,0,0,.06);
    }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      padding: 16px 0; gap: 32px;
    }
    .logo { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
    .logo-icon {
      width: 46px; height: 46px; background: var(--red); border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon svg { width: 26px; height: 26px; }
    .logo-text { line-height: 1.2; }
    .logo-name { font-weight: 800; font-size: 17px; color: var(--navy); letter-spacing: -.02em; }
    .logo-sub { font-size: 11px; color: var(--mid-gray); font-weight: 500; letter-spacing: .04em; text-transform: uppercase; }

    .main-nav ul { display: flex; align-items: center; gap: 4px; }
    .main-nav a {
      padding: 8px 14px; border-radius: 6px; font-size: 14px; font-weight: 500;
      color: var(--text-light); transition: all var(--transition);
    }
    .main-nav a:hover { color: var(--navy); background: var(--warm-gray); }

    .header-actions { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }

    .hamburger {
      display: none; flex-direction: column; gap: 5px; background: none;
      border: none; padding: 6px; cursor: pointer;
    }
    .hamburger span {
      display: block; width: 24px; height: 2px; background: var(--navy);
      border-radius: 2px; transition: all var(--transition);
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile drawer */
    .mobile-nav {
      display: none; position: fixed; top: 0; right: -100%; width: min(320px, 85vw);
      height: 100vh; background: var(--white); z-index: 200;
      box-shadow: -8px 0 40px rgba(0,0,0,.15); transition: right .3s ease;
      flex-direction: column; overflow-y: auto;
    }
    .mobile-nav.open { right: 0; }
    .mobile-nav-header {
      display: flex; align-items: center; justify-content: space-between;
      padding: 20px 24px; border-bottom: 1px solid var(--border);
    }
    .mobile-nav-close {
      background: none; border: none; font-size: 24px; color: var(--text-light); cursor: pointer; line-height: 1;
    }
    .mobile-nav ul { padding: 16px; display: flex; flex-direction: column; gap: 4px; }
    .mobile-nav a {
      display: block; padding: 13px 16px; font-size: 15px; font-weight: 500;
      color: var(--text); border-radius: 8px; transition: all var(--transition);
    }
    .mobile-nav a:hover { background: var(--warm-gray); color: var(--navy); }
    .mobile-nav .btn { width: 100%; margin-top: 8px; }
    .mobile-overlay {
      display: none; position: fixed; inset: 0; background: rgba(0,0,0,.5);
      z-index: 199; opacity: 0; transition: opacity .3s;
    }
    .mobile-overlay.open { display: block; opacity: 1; }

    /* ── Hero ──────────────────────────────────────────────── */
    .hero {
      position: relative; min-height: 620px;
      background: var(--navy-dark);
      display: flex; align-items: center; overflow: hidden;
    }
    .hero-bg {
      position: absolute; inset: 0;
      background:
        linear-gradient(135deg, rgba(27,58,92,.96) 40%, rgba(196,30,58,.55) 100%),
        url('https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?w=1600&q=80&auto=format') center/cover no-repeat;
    }
    .hero-pattern {
      position: absolute; inset: 0; opacity: .06;
      background-image: repeating-linear-gradient(0deg, transparent, transparent 39px, rgba(255,255,255,.5) 39px, rgba(255,255,255,.5) 40px),
                        repeating-linear-gradient(90deg, transparent, transparent 39px, rgba(255,255,255,.5) 39px, rgba(255,255,255,.5) 40px);
    }
    .hero .container { position: relative; z-index: 1; padding-top: 80px; padding-bottom: 80px; }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(196,30,58,.25); border: 1px solid rgba(196,30,58,.5);
      padding: 7px 16px; border-radius: 100px; margin-bottom: 28px;
    }
    .hero-badge-dot { width: 8px; height: 8px; background: var(--red-light); border-radius: 50%; animation: pulse 1.8s infinite; }
    @keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.6;transform:scale(1.3)} }
    .hero-badge span { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.9); letter-spacing: .04em; }

    .hero-title {
      font-family: 'Playfair Display', serif;
      font-size: clamp(36px, 5.5vw, 64px);
      font-weight: 800; line-height: 1.08; color: var(--white);
      margin-bottom: 24px; max-width: 760px;
    }
    .hero-title em { color: var(--red-light); font-style: normal; }
    .hero-subtitle {
      font-size: clamp(16px, 1.8vw, 19px); color: rgba(255,255,255,.82);
      max-width: 580px; margin-bottom: 40px; line-height: 1.65;
    }
    .hero-ctas { display: flex; gap: 14px; flex-wrap: wrap; }

    .hero-stats {
      display: flex; gap: 40px; margin-top: 64px; flex-wrap: wrap;
      border-top: 1px solid rgba(255,255,255,.15); padding-top: 40px;
    }
    .hero-stat-item {}
    .hero-stat-number { font-family: 'Playfair Display', serif; font-size: 28px; font-weight: 800; color: var(--white); }
    .hero-stat-label { font-size: 13px; color: rgba(255,255,255,.6); margin-top: 2px; }

    /* ── Mission ───────────────────────────────────────────── */
    .mission { background: var(--off-white); }
    .mission-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 72px; align-items: center; }
    .mission-visual {
      position: relative; border-radius: 16px; overflow: hidden;
      aspect-ratio: 4/3; background: var(--warm-gray);
    }
    .mission-visual img { width: 100%; height: 100%; object-fit: cover; }
    .mission-visual-badge {
      position: absolute; bottom: 20px; left: 20px; right: 20px;
      background: rgba(27,58,92,.92); backdrop-filter: blur(8px);
      border-radius: 10px; padding: 16px 20px;
      display: flex; align-items: center; gap: 14px;
    }
    .mission-visual-badge-icon { width: 40px; height: 40px; background: var(--red); border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .mission-visual-badge p { font-size: 13px; color: rgba(255,255,255,.85); line-height: 1.4; }
    .mission-visual-badge strong { color: var(--white); font-size: 14px; }
    .mission-principles { display: flex; flex-direction: column; gap: 16px; margin-top: 32px; }
    .principle { display: flex; gap: 14px; align-items: flex-start; }
    .principle-icon { width: 36px; height: 36px; background: rgba(196,30,58,.1); border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px; }
    .principle h4 { font-size: 14px; font-weight: 700; color: var(--navy); margin-bottom: 4px; }
    .principle p { font-size: 14px; color: var(--text-light); }
    .mission-text { font-size: 16px; color: var(--text-light); line-height: 1.75; margin-top: 20px; }
    .mission-founded { margin-top: 28px; padding: 18px 22px; background: var(--white); border-left: 4px solid var(--red); border-radius: 0 8px 8px 0; font-size: 14px; color: var(--text-light); }
    .mission-founded strong { color: var(--navy); font-weight: 700; }

    /* ── Impact Stats ──────────────────────────────────────── */
    .impact { background: var(--navy); }
    .impact-inner { text-align: center; }
    .impact .eyebrow { color: rgba(255,255,255,.6); }
    .impact .section-title { color: var(--white); }
    .impact .section-subtitle { color: rgba(255,255,255,.7); margin: 16px auto 0; }
    .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px; margin-top: 64px; background: rgba(255,255,255,.08); border-radius: 16px; overflow: hidden; }
    .stat-card {
      padding: 48px 32px; text-align: center; background: rgba(255,255,255,.04);
      border-right: 1px solid rgba(255,255,255,.08); transition: background var(--transition);
    }
    .stat-card:last-child { border-right: none; }
    .stat-card:hover { background: rgba(255,255,255,.08); }
    .stat-number {
      font-family: 'Playfair Display', serif;
      font-size: clamp(36px, 4vw, 56px); font-weight: 800;
      color: var(--white); line-height: 1;
    }
    .stat-number span { color: var(--red-light); }
    .stat-label { font-size: 15px; color: rgba(255,255,255,.6); margin-top: 10px; font-weight: 500; }
    .stat-desc { font-size: 13px; color: rgba(255,255,255,.4); margin-top: 6px; line-height: 1.4; }
    .stat-icon { margin: 0 auto 20px; width: 52px; height: 52px; background: rgba(196,30,58,.2); border-radius: 50%; display: flex; align-items: center; justify-content: center; }

    /* ── Programs ──────────────────────────────────────────── */
    .programs { background: var(--white); }
    .programs-grid { display: grid; grid-template-columns: 5fr 7fr; gap: 80px; align-items: start; }
    .programs-intro p { font-size: 16px; color: var(--text-light); margin-top: 20px; line-height: 1.75; }
    .programs-intro .btn { margin-top: 32px; }

    /* Accordion */
    .accordion { margin-top: 0; display: flex; flex-direction: column; gap: 0; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
    .accordion-item { border-bottom: 1px solid var(--border); }
    .accordion-item:last-child { border-bottom: none; }
    .accordion-trigger {
      width: 100%; display: flex; align-items: center; justify-content: space-between;
      padding: 22px 24px; background: none; border: none; text-align: left;
      cursor: pointer; transition: background var(--transition);
    }
    .accordion-trigger:hover { background: var(--off-white); }
    .accordion-trigger.active { background: var(--off-white); }
    .accordion-trigger-left { display: flex; align-items: center; gap: 16px; }
    .accordion-trigger-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .accordion-trigger-icon.red { background: rgba(196,30,58,.1); }
    .accordion-trigger-icon.navy { background: rgba(27,58,92,.1); }
    .accordion-trigger h3 { font-size: 15px; font-weight: 700; color: var(--navy); }
    .accordion-chevron { width: 20px; height: 20px; color: var(--mid-gray); transition: transform var(--transition); flex-shrink: 0; }
    .accordion-trigger.active .accordion-chevron { transform: rotate(180deg); }
    .accordion-content { overflow: hidden; max-height: 0; transition: max-height .35s ease; }
    .accordion-content.open { max-height: 500px; }
    .accordion-body { padding: 0 24px 24px 84px; }
    .accordion-body p { font-size: 14px; color: var(--text-light); line-height: 1.7; }
    .accordion-body a { color: var(--red); font-weight: 600; font-size: 13px; display: inline-flex; align-items: center; gap: 4px; margin-top: 12px; }
    .accordion-body a:hover { text-decoration: underline; }

    /* ── Get Involved ──────────────────────────────────────── */
    .get-involved { background: var(--off-white); }
    .get-involved .section-header { margin-bottom: 48px; }
    .involve-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .involve-card {
      background: var(--white); border-radius: 14px; padding: 36px 30px;
      box-shadow: var(--shadow-sm); transition: all var(--transition);
      display: flex; flex-direction: column;
    }
    .involve-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .involve-card-icon { width: 56px; height: 56px; border-radius: 14px; display: flex; align-items: center; justify-content: center; margin-bottom: 24px; }
    .involve-card-icon.red { background: rgba(196,30,58,.1); }
    .involve-card-icon.navy { background: rgba(27,58,92,.1); }
    .involve-card-icon.teal { background: rgba(13,148,136,.1); }
    .involve-card h3 { font-size: 20px; font-weight: 700; color: var(--navy); margin-bottom: 12px; }
    .involve-card p { font-size: 14px; color: var(--text-light); line-height: 1.7; flex: 1; }
    .involve-card .btn { margin-top: 28px; align-self: flex-start; }

    /* ── News ──────────────────────────────────────────────── */
    .news { background: var(--white); }
    .news-carousel-wrap { position: relative; overflow: hidden; }
    .news-track { display: flex; gap: 24px; transition: transform .4s ease; }
    .news-card {
      min-width: calc(33.333% - 16px); background: var(--white); border: 1px solid var(--border);
      border-radius: 14px; overflow: hidden; flex-shrink: 0;
      box-shadow: var(--shadow-sm); transition: all var(--transition);
    }
    .news-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .news-card-img {
      aspect-ratio: 16/9; overflow: hidden; background: var(--warm-gray);
    }
    .news-card-img img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
    .news-card:hover .news-card-img img { transform: scale(1.04); }
    .news-card-body { padding: 24px; }
    .news-card-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
    .news-card-date { font-size: 12px; color: var(--mid-gray); }
    .news-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); line-height: 1.35; margin-bottom: 10px; }
    .news-card p { font-size: 14px; color: var(--text-light); line-height: 1.65; }
    .news-card-link { display: inline-flex; align-items: center; gap: 6px; margin-top: 16px; font-size: 14px; font-weight: 600; color: var(--red); }
    .news-card-link:hover { text-decoration: underline; }

    .carousel-controls { display: flex; align-items: center; justify-content: flex-end; gap: 10px; margin-top: 32px; }
    .carousel-btn {
      width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--border);
      background: var(--white); display: flex; align-items: center; justify-content: center;
      cursor: pointer; transition: all var(--transition); color: var(--navy);
    }
    .carousel-btn:hover { background: var(--navy); border-color: var(--navy); color: var(--white); }
    .carousel-btn:disabled { opacity: .35; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: var(--white); border-color: var(--border); color: var(--navy); }
    .carousel-dots { display: flex; gap: 6px; margin-right: auto; }
    .carousel-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--border); border: none; cursor: pointer; transition: all var(--transition); padding: 0; }
    .carousel-dot.active { background: var(--red); width: 20px; border-radius: 4px; }

    /* ── Donate CTA ────────────────────────────────────────── */
    .donate-cta {
      background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 50%, #e84060 100%);
      position: relative; overflow: hidden;
    }
    .donate-cta-pattern {
      position: absolute; inset: 0; opacity: .07;
      background-image: radial-gradient(circle at 2px 2px, white 1px, transparent 0);
      background-size: 32px 32px;
    }
    .donate-cta .container { position: relative; z-index: 1; }
    .donate-cta-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .donate-cta .eyebrow { color: rgba(255,255,255,.7); }
    .donate-cta .section-title { color: var(--white); }
    .donate-cta-body { font-size: 17px; color: rgba(255,255,255,.85); margin-top: 20px; line-height: 1.7; }
    .donate-cta-trust { display: flex; align-items: center; gap: 10px; margin-top: 24px; }
    .donate-cta-trust svg { color: rgba(255,255,255,.7); }
    .donate-cta-trust span { font-size: 14px; color: rgba(255,255,255,.75); font-weight: 500; }

    .donate-form { background: var(--white); border-radius: 20px; padding: 36px; box-shadow: var(--shadow-lg); }
    .donate-form h3 { font-size: 20px; font-weight: 700; color: var(--navy); margin-bottom: 24px; }
    .amount-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 16px; }
    .amount-btn {
      padding: 13px 8px; border: 2px solid var(--border); border-radius: 8px;
      background: var(--white); font-size: 15px; font-weight: 700; color: var(--navy);
      cursor: pointer; transition: all var(--transition); text-align: center;
    }
    .amount-btn:hover { border-color: var(--red); color: var(--red); }
    .amount-btn.selected { background: var(--red); border-color: var(--red); color: var(--white); }
    .amount-btn.custom { font-size: 13px; font-weight: 600; }
    .amount-impact { font-size: 13px; color: var(--text-light); text-align: center; margin-bottom: 20px; min-height: 20px; }
    .amount-impact strong { color: var(--navy); }
    .donate-form-submit { width: 100%; padding: 16px; background: var(--red); color: var(--white); border: none; border-radius: 10px; font-size: 16px; font-weight: 700; cursor: pointer; transition: all var(--transition); }
    .donate-form-submit:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: 0 4px 14px rgba(196,30,58,.4); }
    .donate-form-note { font-size: 12px; color: var(--mid-gray); text-align: center; margin-top: 14px; }

    /* ── Modal ─────────────────────────────────────────────── */
    .modal-overlay {
      position: fixed; inset: 0; background: rgba(0,0,0,.6); z-index: 300;
      display: flex; align-items: center; justify-content: center; padding: 20px;
      opacity: 0; pointer-events: none; transition: opacity .25s;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }
    .modal {
      background: var(--white); border-radius: 20px; padding: 44px;
      width: 100%; max-width: 520px; position: relative;
      transform: translateY(20px); transition: transform .25s;
      max-height: 90vh; overflow-y: auto;
    }
    .modal-overlay.open .modal { transform: none; }
    .modal-close {
      position: absolute; top: 16px; right: 16px; width: 36px; height: 36px;
      border-radius: 50%; border: 1px solid var(--border); background: var(--white);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; font-size: 18px; color: var(--text-light); transition: all var(--transition);
    }
    .modal-close:hover { background: var(--warm-gray); }
    .modal h2 { font-family: 'Playfair Display', serif; font-size: 28px; font-weight: 800; color: var(--navy); margin-bottom: 6px; }
    .modal-sub { font-size: 15px; color: var(--text-light); margin-bottom: 28px; }
    .modal .amount-grid { grid-template-columns: repeat(3, 1fr); }
    .modal-input-wrap { margin-bottom: 20px; }
    .modal-input-wrap label { display: block; font-size: 13px; font-weight: 600; color: var(--navy); margin-bottom: 8px; }
    .modal-input-wrap input {
      width: 100%; padding: 13px 16px; border: 2px solid var(--border);
      border-radius: 8px; font-size: 15px; font-family: inherit;
      transition: border-color var(--transition); color: var(--text);
    }
    .modal-input-wrap input:focus { outline: none; border-color: var(--red); }

    /* ── Footer ────────────────────────────────────────────── */
    .site-footer { background: var(--navy-dark); }
    .footer-top { padding: 72px 0 48px; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px; }
    .footer-brand .logo { margin-bottom: 20px; }
    .footer-brand p { font-size: 14px; color: rgba(255,255,255,.55); line-height: 1.7; max-width: 260px; }
    .footer-social { display: flex; gap: 10px; margin-top: 24px; }
    .footer-social a {
      width: 36px; height: 36px; border-radius: 8px; background: rgba(255,255,255,.08);
      display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,.6); transition: all var(--transition); font-size: 14px;
    }
    .footer-social a:hover { background: var(--red); color: var(--white); }
    .footer-col h4 { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: rgba(255,255,255,.45); margin-bottom: 20px; }
    .footer-col ul { display: flex; flex-direction: column; gap: 10px; }
    .footer-col a { font-size: 14px; color: rgba(255,255,255,.65); transition: color var(--transition); }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,.08); padding: 24px 0; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
    .footer-bottom p { font-size: 13px; color: rgba(255,255,255,.4); }
    .footer-bottom-links { display: flex; gap: 20px; }
    .footer-bottom-links a { font-size: 13px; color: rgba(255,255,255,.4); transition: color var(--transition); }
    .footer-bottom-links a:hover { color: rgba(255,255,255,.75); }

    /* ── Animations ────────────────────────────────────────── */
    .fade-in { opacity: 0; transform: translateY(24px); transition: opacity .6s ease, transform .6s ease; }
    .fade-in.visible { opacity: 1; transform: none; }

    /* ── Responsive ────────────────────────────────────────── */
    @media (max-width: 1100px) {
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-brand { grid-column: 1 / -1; }
      .programs-grid { grid-template-columns: 1fr; gap: 48px; }
    }
    @media (max-width: 900px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .mission-grid { grid-template-columns: 1fr; gap: 40px; }
      .donate-cta-inner { grid-template-columns: 1fr; gap: 40px; }
      .involve-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .utility-bar { display: none; }
      .main-nav, .header-actions .btn { display: none; }
      .hamburger { display: flex; }
      .mobile-nav { display: flex; }
      .section { padding: 60px 0; }
      .hero { min-height: auto; }
      .hero .container { padding-top: 56px; padding-bottom: 56px; }
      .hero-title { font-size: 32px; }
      .hero-subtitle { font-size: 16px; }
      .hero-stats { gap: 28px; margin-top: 44px; padding-top: 28px; }
      .hero-stat-number { font-size: 22px; }
      .stats-grid { grid-template-columns: 1fr 1fr; border-radius: 12px; }
      .stat-card { padding: 32px 20px; border-right: none; border-bottom: 1px solid rgba(255,255,255,.08); }
      .stat-card:nth-child(odd) { border-right: 1px solid rgba(255,255,255,.08); }
      .stat-card:last-child { border-bottom: none; }
      .involve-grid { grid-template-columns: 1fr; }
      .news-card { min-width: calc(85vw); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; text-align: center; }
      .amount-grid { grid-template-columns: repeat(3, 1fr); }
      .accordion-body { padding-left: 24px; }
      .section-title { font-size: 26px; }
    }
    @media (max-width: 480px) {
      .hero-ctas { flex-direction: column; }
      .hero-ctas .btn { width: 100%; }
      .stats-grid { grid-template-columns: 1fr; }
      .stat-card { border-right: none !important; }
      .amount-grid { grid-template-columns: repeat(2, 1fr); }
      .donate-form { padding: 24px; }
      .modal { padding: 28px 20px; }
    }

    /* ── Counter animation ─────────────────────────────────── */
    .count-up { display: inline; }
  </style>
</head>
