<!-- ── Scripts ────────────────────────────────────────────────── -->
<script>
  // ── Hamburger / Mobile Nav ──────────────────────────────────
  const hamburger = document.getElementById('hamburgerBtn');
  const mobileNav = document.getElementById('mobileNav');
  const overlay = document.getElementById('mobileOverlay');

  function openMobileNav() {
    hamburger.classList.add('open');
    mobileNav.classList.add('open');
    overlay.classList.add('open');
    hamburger.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
  }
  function closeMobileNav() {
    hamburger.classList.remove('open');
    mobileNav.classList.remove('open');
    overlay.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }
  hamburger.addEventListener('click', () => {
    mobileNav.classList.contains('open') ? closeMobileNav() : openMobileNav();
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') { closeMobileNav(); closeModal(); }
  });

  // ── Accordion ───────────────────────────────────────────────
  function toggleAccordion(trigger) {
    const isOpen = trigger.classList.contains('active');
    // Close all
    document.querySelectorAll('.accordion-trigger').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-expanded', 'false');
    });
    document.querySelectorAll('.accordion-content').forEach(c => c.classList.remove('open'));
    // Open clicked if it was closed
    if (!isOpen) {
      trigger.classList.add('active');
      trigger.setAttribute('aria-expanded', 'true');
      const panelId = trigger.getAttribute('aria-controls');
      document.getElementById(panelId).classList.add('open');
    }
  }

  // ── News Carousel ───────────────────────────────────────────
  const track = document.getElementById('newsTrack');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');
  const dots = document.querySelectorAll('.carousel-dot');
  let currentSlide = 0;
  const totalSlides = 2; // 4 cards, show 3 at a time => 2 positions

  function updateCarousel() {
    const cardWidth = track.querySelector('.news-card').offsetWidth + 24;
    const visibleCount = window.innerWidth <= 768 ? 1 : 3;
    const maxSlide = 4 - visibleCount;
    const clampedSlide = Math.min(currentSlide, maxSlide);
    track.style.transform = `translateX(-${clampedSlide * cardWidth}px)`;
    prevBtn.disabled = clampedSlide === 0;
    nextBtn.disabled = clampedSlide >= maxSlide;
    dots.forEach((d, i) => d.classList.toggle('active', i === Math.min(clampedSlide, dots.length - 1)));
  }

  function nextSlide() { currentSlide = Math.min(currentSlide + 1, 3); updateCarousel(); }
  function prevSlide() { currentSlide = Math.max(currentSlide - 1, 0); updateCarousel(); }
  function goToSlide(n) { currentSlide = n; updateCarousel(); }
  window.addEventListener('resize', updateCarousel);

  // ── Donation Modal ──────────────────────────────────────────
  const modal = document.getElementById('donateModal');

  function openModal() {
    modal.classList.add('open');
    document.body.style.overflow = 'hidden';
    modal.querySelector('.modal-close').focus();
  }
  function closeModal() {
    modal.classList.remove('open');
    document.body.style.overflow = '';
  }
  function handleOverlayClick(e) {
    if (e.target === modal) closeModal();
  }

  const impactMap = {
    25: '$25 — Provides 5 emergency blankets for displaced families',
    50: '$50 — Supplies a family with food and water for one week',
    100: '$100 — Funds emergency shelter materials for a household',
    250: '$250 — Equips a volunteer with disaster response training',
    500: '$500 — Funds two weeks of emergency operations in a disaster zone',
  };

  function selectAmount(btn, amount) {
    btn.closest('.donate-form').querySelectorAll('.amount-btn').forEach(b => {
      b.classList.remove('selected'); b.setAttribute('aria-pressed', 'false');
    });
    btn.classList.add('selected'); btn.setAttribute('aria-pressed', 'true');
    const impactEl = document.getElementById('inlineImpact');
    const customWrap = document.getElementById('inlineCustomWrap');
    if (amount === 'custom') {
      impactEl.innerHTML = 'Enter your custom amount below';
      customWrap.style.display = 'block';
    } else {
      impactEl.innerHTML = `<strong>$${amount}</strong> — ${impactMap[amount]?.split('—')[1]?.trim() || 'Every dollar counts toward saving lives'}`;
      customWrap.style.display = 'none';
    }
  }

  function selectModalAmount(btn, amount) {
    btn.closest('.modal').querySelectorAll('.amount-btn').forEach(b => {
      b.classList.remove('selected'); b.setAttribute('aria-pressed', 'false');
    });
    btn.classList.add('selected'); btn.setAttribute('aria-pressed', 'true');
    const impactEl = document.getElementById('modalImpact');
    const customWrap = document.getElementById('modalCustomWrap');
    if (amount === 'custom') {
      impactEl.innerHTML = 'Enter your custom amount below';
      customWrap.style.display = 'block';
    } else {
      impactEl.innerHTML = `<strong>$${amount}</strong> — ${impactMap[amount]?.split('—')[1]?.trim() || 'Every dollar counts toward saving lives'}`;
      customWrap.style.display = 'none';
    }
  }

  function submitDonation() {
    const name = document.getElementById('donorName').value.trim();
    const email = document.getElementById('donorEmail').value.trim();
    if (!name || !email) {
      alert('Please fill in your name and email to continue.');
      return;
    }
    // In production this would integrate with a payment processor
    closeModal();
    showThankYou();
  }

  function showThankYou() {
    const div = document.createElement('div');
